"use client";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-switch";
export const switchVariants = cva(
  "v-switch [position:relative] [display:inline-block] [border-radius:var(--r-pill)] [flex:none] [cursor:pointer] [width:48px] [height:28px] [background:var(--v-beige)] [box-shadow:inset_0_0_0_1px_var(--v-edge)]",
);
export type SwitchProps = React.ComponentProps<typeof Primitive.Root>;
export function Switch({ className, ref, ...props }: SwitchProps) {
  const morphRef = useMorph<HTMLButtonElement>("controls", ref);
  return (
    <Primitive.Root
      ref={morphRef}
      data-slot="switch"
      data-part="root"
      className={cn(switchVariants(), className)}
      {...props}
    >
      <Primitive.Thumb data-slot="switch-thumb" data-part="thumb" />
    </Primitive.Root>
  );
}
export type SwitchRowProps = React.ComponentProps<"label">;
export function SwitchRow({ className, ...props }: SwitchRowProps) {
  return (
    <label
      data-slot="switch-row"
      className={cn("v-switchrow", className)}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]) {
  transition: background var(--t-element) var(--enter);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])
  > [data-slot="switch-thumb"] {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--v-canvas);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  transition: transform var(--t-element) var(--enter);
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[aria-checked="true"],
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"] {
  background: var(--v-ink);
  box-shadow: none;
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[aria-checked="true"]
  > [data-slot="switch-thumb"],
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]
  > [data-slot="switch-thumb"] {
  transform: translateX(18px);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]):not(
    [aria-checked="true"]
  ):not([data-state="checked"]) {
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled] {
  cursor: not-allowed;
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled] {
  cursor: not-allowed;
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])
  > [data-slot="switch-thumb"] {
  background: var(--switch-knob);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[aria-checked="true"]
  > [data-slot="switch-thumb"],
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]
  > [data-slot="switch-thumb"] {
  background: var(--switch-knob-on);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled] {
  background: var(--v-disabled-face);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled]
  > [data-slot="switch-thumb"] {
  background: var(--v-disabled-edge);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])
  > [data-slot="switch-thumb"],
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])::before {
  pointer-events: none;
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]) {
  transition:
    background var(--t-element) var(--enter),
    box-shadow var(--t-element);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])
  > [data-slot="switch-thumb"] {
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1.5px var(--v-edge);
  transition:
    transform var(--t-max) cubic-bezier(0.34, 1.4, 0.44, 1),
    border-radius var(--t-max) var(--enter),
    background var(--t-element),
    box-shadow var(--t-element);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]):hover {
  background: color-mix(in oklab, var(--v-beige) 90%, var(--v-ink));
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]):hover
  > [data-slot="switch-thumb"] {
  box-shadow: inset 0 0 0 1.5px var(--v-text);
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"],
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[aria-checked="true"] {
  background: var(--sw, var(--v-pink));
  box-shadow: none;
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]
  > [data-slot="switch-thumb"],
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[aria-checked="true"]
  > [data-slot="switch-thumb"] {
  transform: translateX(20px);
  background: var(--ink-fixed);
  box-shadow: none;
  border-radius: 50% 46% 54% 50%/46% 50% 50% 54%;
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]:hover {
  background: color-mix(
    in oklab,
    var(--sw, var(--v-pink)) 88%,
    var(--ink-fixed)
  );
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]):active
  > [data-slot="switch-thumb"] {
  transform: scaleX(1.18);
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]:active
  > [data-slot="switch-thumb"] {
  transform: translateX(18px) scaleX(1.18);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-olive {
  --sw: var(--v-olive);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-blue {
  --sw: var(--v-blue);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-yellow {
  --sw: var(--v-yellow);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-ink {
  --sw: var(--v-ink);
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  ).-ink[data-state="checked"]
  > [data-slot="switch-thumb"] {
  background: var(--v-canvas);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-sm {
  width: 38px;
  height: 22px;
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"]).-sm
  > [data-slot="switch-thumb"] {
  width: 16px;
  height: 16px;
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  ).-sm[data-state="checked"]
  > [data-slot="switch-thumb"] {
  transform: translateX(16px);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled] {
  background: var(--v-disabled-face);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
}
.v-switch:where([data-slot="switch"], [data-slot^="switch-"])[data-disabled]
  > [data-slot="switch-thumb"] {
  background: var(--v-disabled-edge);
  box-shadow: none;
}
.v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-disabled][data-state="checked"] {
  background: color-mix(in oklab, var(--v-pink) 40%, var(--v-disabled-face));
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2px 16px;
  align-items: center;
  min-height: 56px;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in oklab, var(--v-border) 70%, transparent);
  cursor: pointer;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]):last-child {
  border-bottom: 0;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]) > b {
  font-weight: 500;
  font-size: 15px;
  line-height: 1.3;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]) > small {
  grid-column: 1;
  font-size: 13px;
  color: var(--v-text-2);
  line-height: 1.4;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]) > .v-switch {
  grid-column: 2;
  grid-row: 1 / span 2;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]):has(
    [data-slot="switch"][data-disabled]
  ) {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]):has(
    [data-slot="switch"][data-disabled]
  )
  > small {
  color: var(--v-disabled-ink);
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]).-card {
  padding: 12px 16px;
  border-radius: 18px;
  background: var(--card);
  border-bottom: 0;
}
.v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]).-card:has(
    [data-slot="switch"][data-state="checked"]
  ) {
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1.5px var(--sw, var(--v-pink));
}
:root[data-mode="dark"]
  .v-switch:where([data-slot="switch"], [data-slot^="switch-"]) {
  background: var(--v-beige-2);
}
:root[data-mode="dark"]
  .v-switch:where([data-slot="switch"], [data-slot^="switch-"])
  > [data-slot="switch-thumb"] {
  background: var(--v-text-2);
  box-shadow: none;
}
:root[data-mode="dark"]
  .v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  )[data-state="checked"]
  > [data-slot="switch-thumb"] {
  background: var(--ink-fixed);
}
:root[data-mode="dark"]
  .v-switch:where(
    [data-slot="switch"],
    [data-slot^="switch-"]
  ).-ink[data-state="checked"] {
  background: var(--v-pink);
}
:root[data-mode="dark"]
  .v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]).-card:has(
    [data-slot="switch"][data-state="checked"]
  ) {
  background: var(--v-beige-2);
}
:root[data-mode="dark"]
  .v-switchrow:where([data-slot="switch"], [data-slot^="switch-"]).-card {
  background: var(--v-beige);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="switch"],
  [data-slot^="switch-"],
  [data-slot="switch"]::before,
  [data-slot="switch"]::after,
  [data-slot^="switch-"]::before,
  [data-slot^="switch-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* Preserve the source :has(input:disabled:checked) precedence over the dark base. */
:root[data-mode="dark"] .v-switch:where([data-slot="switch"])[data-disabled][data-state="checked"] {
  background: color-mix(in oklab, var(--v-pink) 40%, var(--v-disabled-face));
}

}
